(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.018+t*0.3)*18 + Math.cos(y*0.013-t*0.2)*12;
  const w1y = Math.cos(y*0.018-t*0.25)*18 + Math.sin(x*0.016+t*0.35)*12;
  const w2x = Math.sin((x+y)*0.01+t*0.15)*8 + Math.cos((x-y)*0.012-t*0.18)*6;
  const w2y = Math.cos((x-y)*0.01-t*0.2)*8 + Math.sin((x+y)*0.011+t*0.22)*6;
  const sx = x+w1x+w2x, sy = y+w1y+w2y;
  const src = [
    [160+Math.sin(t*0.6)*100, 80+Math.cos(t*0.4)*50, 0.08, 2.0, 1.0],
    [320+Math.cos(t*0.5)*100, 160+Math.sin(t*0.7)*50, 0.1, 1.7, 0.85],
    [240+Math.sin(t*0.3+2)*140, 120+Math.cos(t*0.5+1)*90, 0.06, 2.3, 1.1],
    [120+Math.cos(t*0.8+1)*80, 180+Math.sin(t*0.6+3)*60, 0.12, 1.5, 0.9],
    [360+Math.sin(t*0.4+4)*90, 60+Math.cos(t*0.9+2)*70, 0.07, 2.6, 0.95],
    [240+Math.cos(t*0.35+5)*120, 200+Math.sin(t*0.55)*80, 0.09, 1.9, 1.05],
    [80+Math.sin(t*0.45+3)*110, 120+Math.cos(t*0.65+2)*70, 0.11, 2.1, 0.88],
    [400+Math.cos(t*0.55+1)*70, 200+Math.sin(t*0.75+4)*50, 0.085, 1.8, 1.12]
  ];
  let aS=0, iS=0, cS=0;
  for (const [sX,sY,f,sp,w] of src) {
    const d=Math.sqrt((sx-sX)**2+(sy-sY)**2);
    aS += Math.sin(d*f-t*sp)*w;
    iS += Math.sin(d*f*0.7+t*sp*0.6+1.5)*w;
    cS += Math.cos(d*f*0.5-t*sp*0.4+2.8)*w*0.5;
  }
  const n=8, act=aS/n, inh=iS/n, cor=cS/n;
  const bg=(Math.sin(sx*0.04+sy*0.025+t*0.8)+Math.sin(sx*0.03-sy*0.04+t*1.1))/2+Math.sin((sx+sy)*0.12+t*2.5)*0.2+Math.sin((sx-sy)*0.1-t*2)*0.2;
  const dist=Math.sqrt((sx-cx)**2+(sy-cy)**2), ang=Math.atan2(sy-cy,sx-cx);
  const spiral=(Math.sin(dist*0.05-ang*3-t*1.5)+Math.sin(dist*0.04+ang*4-t*1.2))*0.4;
  const micro=(Math.sin(sx*0.22+t*1.8)*Math.sin(sy*0.22-t*1.4)+Math.sin((sx-sy)*0.18+t*2.2)*0.5)*0.15;
  const reaction=Math.tanh((act-inh*0.65+bg*0.25+spiral+cor*0.3+micro)*2.0);
  const cell=Math.tanh((Math.sin(sx*0.15)*Math.sin(sy*0.15)+Math.sin((sx+sy)*0.1+t)*0.5)*1.5)*0.3;
  const laplacian=Math.sin(sx*0.08+1.5)*Math.sin(sy*0.08+0.7)*0.12;
  const diffusion=Math.tanh((reaction-laplacian*3.5)*1.8)*0.3;
  const blend=reaction*0.55+cell*0.15+diffusion*0.3, v=blend*0.5+0.5;
  const pal=[[12,8,42],[28,22,88],[18,72,118],[16,128,132],[42,168,118],[168,188,72],[218,162,58],[198,88,62],[158,42,72],[88,18,58],[12,8,42]];
  const idx=v*(pal.length-1), i=Math.min(idx|0,pal.length-2), f=idx-i;
  const sm=pal[i][0]+(pal[i+1][0]-pal[i][0])*f;
  const sg=pal[i][1]+(pal[i+1][1]-pal[i][1])*f;
  const sb=pal[i][2]+(pal[i+1][2]-pal[i][2])*f;
  const lum=0.82+Math.sin(reaction*Math.PI)*0.18;
  const edge=Math.abs(reaction)>0.65?1.12:Math.abs(reaction)>0.35?1.04:0.92;
  const glow=Math.max(0,Math.abs(reaction)-0.6)*2.5;
  const shift=Math.sin(t*0.2+dist*0.01)*8;
  return [
    Math.min(255,Math.max(0,(sm+shift)*lum*edge+glow*30))|0,
    Math.min(255,Math.max(0,sg*lum*edge+glow*18))|0,
    Math.min(255,Math.max(0,(sb-shift*0.5)*lum*edge+glow*22))|0
  ];
}
